<?php
declare(strict_types=1);
require_once __DIR__.'/journey.php';
require_once __DIR__.'/devices.php';
function assetDir(): string {return getenv('HOTEL_ASSET_DIR') ?: storage().'/assets';}
function storage(): string { $p=getenv('HOTEL_DATA_DIR') ?: dirname(__DIR__,2).'/hotell-private'; if(!is_dir($p)) mkdir($p,0700,true); return $p; }
function transact(callable $fn) { $p=storage(); $l=fopen($p.'/lock','c'); if(!$l||!flock($l,LOCK_EX)) throw new RuntimeException('Lagringen er opptatt.'); try { $db=is_file($p.'/state.json')?json_decode(file_get_contents($p.'/state.json'),true,512,JSON_THROW_ON_ERROR):['hotels'=>[],'keys'=>[],'invites'=>[]]; $r=$fn($db); $tmp=$p.'/state.'.bin2hex(random_bytes(6)).'.tmp'; file_put_contents($tmp,json_encode($db,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)); chmod($tmp,0600); rename($tmp,$p.'/state.json'); return $r; } finally {flock($l,LOCK_UN);fclose($l);} }
function fail(string $message,int $status=400): never { throw new HotelError($message,$status); }
class HotelError extends RuntimeException {}
function token(): string {return bin2hex(random_bytes(32));}
function auth(array $db): ?array { $k=$_COOKIE['hotel_device']??''; $h=hash('sha256',$k); return $db['keys'][$h]??null; }
function initial(bool $qa=false,int $seconds=300): array { $players=[]; foreach(['bianca'=>'Bianca','leandra'=>'Leandra','rebecca'=>'Rebecca'] as $id=>$name) $players[]=['id'=>$id,'name'=>$qa?'Test '.$name:$name,'role'=>'fri','seen'=>0,'ready'=>false,'lastSmall'=>0]; $rooms=[]; for($i=1;$i<=6;$i++)$rooms[]=['id'=>$i,'color'=>['peach','mint','lavender'][$i%3],'decor'=>'flowers']; return ['rev'=>1,'qa'=>$qa,'daySeconds'=>$qa?max(3,$seconds):300,'season'=>1,'hotelName'=>'Hotellet vårt','phase'=>'planning','day'=>0,'dayEndsAt'=>0,'profile'=>'koselig','audience'=>'familier','priority'=>'rom','rooms'=>$rooms,'players'=>$players,'metrics'=>['joy'=>65,'cleanliness'=>85,'energy'=>85,'reputation'=>50,'coins'=>100],'upgrades'=>[],'guests'=>[],'event'=>null,'proposal'=>null,'newspaper'=>[],'keepsakes'=>[],'history'=>[],'handled'=>[]]; }
function effect(array &$s,array $e): void { foreach($e as $k=>$v)$s['metrics'][$k]=max(0,min($k==='coins'?999:100,$s['metrics'][$k]+$v)); foreach($s['guests'] as &$g){$g['mood']=max(0,min(100,($g['mood']??65)+($e['joy']??0)));$g['bubble']=$s['metrics']['cleanliness']<45?'Kan noen rydde litt?':($s['metrics']['joy']>=70?'Her vil jeg bo igjen!':'Hva skjer i hagen i dag?');} unset($g); }
function present(array $s,int $now): array {return array_values(array_column(array_filter($s['players'],fn($p)=>$p['seen']>=$now-45),'id'));}
function guestTradeoff(array &$s,string $kind): void {foreach($s['guests'] as &$g){$delta=0;$bubble='';if($kind==='party'){ $delta=$g['kind']==='rolig'?-20:10;$bubble=$g['kind']==='rolig'?'Jeg skulle ønske det var roligere.':'Kan vi danse litt til?';}if($kind==='pets'){$delta=$g['allergy']?-20:8;$bubble=$g['allergy']?'Jeg trenger et rom uten dyr.':'Så koselig med hund på besøk!';}if($kind==='pool'){$delta=$g['kind']==='aktiv'?15:3;$bubble='Jeg gleder meg til å bade!';$g['status']='pool';}if($delta){$g['mood']=max(0,min(100,$g['mood']+$delta));$g['bubble']=$bubble;}}unset($g);}
function publicState(array $s,int $now): array {sceneVisuals($s);$s['hotelName']=$s['hotelName']??'Hotellet vårt';unset($s['handled'],$s['qa'],$s['dayPlan'],$s['usedEvents'],$s['usedStories'],$s['usedTasks'],$s['storyChoices']);foreach($s['players'] as &$p){$p['online']=$p['seen']>=$now-45;unset($p['lastSmall'],$p['seen']);}unset($p);return $s;}
function action(array &$s,string $who,array $in,int $now): void { $a=$in['action']??'';migrateJourney($s,$now);if(journeyAction($s,$who,$in,$now)){$s['rev']++;return;}foreach($s['players'] as &$p)if($p['id']===$who){$player=&$p;break;}unset($p);
 if($a==='role'){if(!in_array($in['role']??'', ['fri','resepsjon','rom','hage','kjokken']))fail('Velg en rolle.');$player['role']=$in['role'];}
 elseif($a==='configure'){if($s['phase']!=='planning')fail('Neste sesong kan planlegges etter dag fem.'); if(array_key_exists('hotelName',$in)){$name=$in['hotelName'];if(!is_string($name)||strlen($name)>160||!preg_match('//u',$name)||preg_match('/[<>\p{C}]/u',$name))fail('Hotellnavnet må ha 2–40 tegn, uten spesialkoder.');$name=preg_replace('/^\s+|\s+$/u','',$name);if(!preg_match('/^.{2,40}$/uD',$name))fail('Hotellnavnet må ha 2–40 tegn.');$s['hotelName']=$name;} foreach(['profile'=>['koselig','luksus','natur'],'audience'=>['familier','venner','rolige'],'priority'=>['rom','mat','aktiviteter','personale']] as $k=>$allowed)if(isset($in[$k])){if(!in_array($in[$k],$allowed,true))fail('Ukjent valg.');$s[$k]=$in[$k];}foreach($s['players'] as &$p)$p['ready']=false;unset($p);}
 elseif($a==='decorate'){ $i=(int)($in['room']??0)-1;if($i<0||$i>5)fail('Ukjent rom.');if(isset($in['color'])){if(!in_array($in['color'],['peach','mint','lavender','sky','sunshine','rose']))fail('Ukjent farge.');$s['rooms'][$i]['color']=$in['color'];}if(isset($in['decor'])){if(!in_array($in['decor'],array_merge(['flowers','plant','stars','books'], $s['keepsakes'])))fail('Pynten er ikke tilgjengelig.');$s['rooms'][$i]['decor']=$in['decor'];}}
 elseif($a==='small'){if($s['phase']!=='day')fail('Åpne hotellet først.');$effects=['welcome'=>['joy'=>3,'reputation'=>1],'clean'=>['cleanliness'=>8,'energy'=>-2],'serve'=>['joy'=>5,'energy'=>-2],'garden'=>['joy'=>3,'energy'=>2]];$kind=$in['kind']??'';if(!isset($effects[$kind]))fail('Ukjent handling.');if($now-$player['lastSmall']<3)fail('Et lite øyeblikk – du hjelper allerede.',429);if(($player['helpedScene']??'')===$s['event']['id'])fail('Du har hjulpet til her. Se på oppgavene eller neste del av dagen.');$player['helpedScene']=$s['event']['id'];$player['lastSmall']=$now;effect($s,$effects[$kind]);foreach($s['guests'] as &$g){if($kind==='welcome'&&$g['status']==='queue'){$g['status']='room';$g['need']='serve';$g['bubble']='Takk for hjelpen! Nå finner jeg rommet.';break;}if($kind==='serve'&&$g['need']==='serve'){$g['status']='dining';$g['need']='relax';$g['bubble']='Frokosten smaker godt!';$g['mood']=min(100,$g['mood']+8);break;}if($kind==='clean'){$g['bubble']='Så fint det ble her!';$g['mood']=min(100,$g['mood']+3);}}unset($g);}
 elseif($a==='propose'){if($s['phase']!=='day')fail('Forslag gjøres i løpet av dagen.');if($s['proposal'])fail('Stem på forslaget som allerede ligger der.');$kind=$in['kind']??'';if(!in_array($kind,['pool','party','pets','quiet','event']))fail('Ukjent forslag.');if($kind==='pool'&&(in_array('pool',$s['upgrades'])||$s['metrics']['coins']<30))fail('Basseng er allerede bygget eller dere trenger flere hotellmynter.');if($kind==='event'&&$s['event']['resolved'])fail('Hendelsen er allerede løst.');$choice=$kind==='event'?($in['choice']??'a'):'yes';if($kind==='event'&&!in_array($choice,['a','b']))fail('Ukjent valg.');if($kind==='event'){foreach($s['event']['choices'] as $option)if($option['id']===$choice&&$s['metrics']['coins']+($option['effect']['coins']??0)<0)fail('Dere trenger flere hotellmynter for dette valget. Velg den andre løsningen.');}$s['proposal']=['id'=>token(),'kind'=>$kind,'by'=>$who,'votes'=>[$who=>$choice],'createdAt'=>$now];resolveVote($s,$now);}
 elseif($a==='vote'){if(!$s['proposal'])fail('Ingen forslag å stemme på.');$choice=$in['choice']??'';$allowed=$s['proposal']['kind']==='event'?['a','b']:['yes','no'];if(!in_array($choice,$allowed))fail('Ukjent stemme.');if($s['proposal']['kind']==='event'){foreach($s['event']['choices'] as $option)if($option['id']===$choice&&$s['metrics']['coins']+($option['effect']['coins']??0)<0)fail('Dere trenger flere hotellmynter for dette valget. Velg den andre løsningen.');}$s['proposal']['votes'][$who]=$choice;resolveVote($s,$now);}
 elseif($a==='ready'){if(!in_array($s['phase'],['planning','evening']))fail('Vent til dagen er ferdig.');$player['ready']=true;$active=present($s,$now);$ready=array_column(array_filter($s['players'],fn($p)=>$p['ready']),'id');if(!array_diff($active,$ready))startDay($s,$now);}
 elseif($a==='newSeason'){if($s['phase']!=='finished')fail('Fullfør sesongen først.');$s['season']++;$s['phase']='planning';$s['day']=0;$s['event']=null;$s['guests']=[];$s['newspaper']=[];$s['history']=[];$s['dayPlan']=[];$s['tasks']=[];$s['metrics']['energy']=85;$s['metrics']['cleanliness']=85;foreach($s['players'] as &$p)$p['ready']=false;unset($p);}
 else fail('Ukjent handling.');$s['rev']++;
}

function ownerCommand(string $cmd,string $hotel,array $argv): array {return transact(function(&$db)use($cmd,$hotel,$argv){if($cmd==='create'){if(isset($db['hotels'][$hotel]))fail('Hotel exists.');$db['hotels'][$hotel]=initial(($argv[3]??'')==='qa',(int)($argv[4]??300));return ['created'=>$hotel];}if(!isset($db['hotels'][$hotel]))fail('Unknown hotel.');if($cmd==='status')return ['hotel'=>$hotel,'qa'=>$db['hotels'][$hotel]['qa'],'phase'=>$db['hotels'][$hotel]['phase'],'day'=>$db['hotels'][$hotel]['day'],'bindings'=>count(array_filter($db['keys'],fn($k)=>$k['hotel']===$hotel)),'players'=>array_map(function($p)use($db,$hotel){$bound=false;foreach($db['keys'] as $k)if($k['hotel']===$hotel&&$k['player']===$p['id'])$bound=true;$expires=null;foreach($db['invites'] as $v)if($v['hotel']===$hotel&&$v['player']===$p['id']&&$v['expires']>=time())$expires=$v['expires'];return ['id'=>$p['id'],'name'=>$p['name'],'bound'=>$bound,'devices'=>count(array_filter($db['keys'],fn($k)=>$k['hotel']===$hotel&&$k['player']===$p['id'])),'inviteExpiresAt'=>$expires];},$db['hotels'][$hotel]['players'])];if($cmd==='delete-qa'){if(!$db['hotels'][$hotel]['qa'])fail('Only QA hotels can be deleted.');unset($db['hotels'][$hotel]);foreach(['keys','invites','deviceCodes'] as $table)foreach(($db[$table]??[]) as $key=>$v)if($v['hotel']===$hotel)unset($db[$table][$key]);return ['deleted'=>$hotel];}if(!in_array($cmd,['invite','reset']))fail('Unknown command.');$player=$argv[3]??'';if(!in_array($player,['bianca','leandra','rebecca']))fail('Unknown player.');if($cmd==='invite')foreach($db['keys'] as $k)if($k['hotel']===$hotel&&$k['player']===$player)fail('Player already bound; use reset to replace device.');foreach(['keys','invites','deviceCodes'] as $table)foreach(($db[$table]??[]) as $key=>$v)if($v['hotel']===$hotel&&$v['player']===$player)unset($db[$table][$key]);$t=token();$db['invites'][hash('sha256',$t)]=['hotel'=>$hotel,'player'=>$player,'expires'=>time()+7*86400];return ['player'=>$player,'url'=>'https://biancanoor.no/hotell/#invite='.$t,'expiresInDays'=>7];});}
